CREATE OR REPLACE FUNCTION app.enqueue_notification(p_tenant uuid, p_customer uuid, p_kind text, p_channels text[], p_payload jsonb, p_dedupe text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_ch text;
  v_n int := 0;
  v_marketing boolean := p_kind in ('offer', 'news_promo');
  v_phone text;
begin
  select phone into v_phone from public.customers where id = p_customer;
  foreach v_ch in array p_channels loop
    if v_ch <> 'inapp' and v_marketing and not app.has_marketing_consent(p_customer, v_ch) then continue; end if;
    if not app.pref_enabled(p_customer, case when p_kind = 'news_promo' then 'offer' else p_kind end, v_ch) then continue; end if;
    if v_ch = 'sms' and v_phone is null then continue; end if;
    insert into public.notification_queue (tenant_id, customer_id, channel, kind, payload, dedupe_key)
    values (p_tenant, p_customer, v_ch, p_kind, p_payload, case when p_dedupe is null then null else p_dedupe || ':' || v_ch end)
    on conflict (dedupe_key) do nothing;
    v_n := v_n + 1;
  end loop;
  return v_n;
end
$function$

CREATE OR REPLACE FUNCTION app.free_slot_news(p_tenant uuid, p_start timestamp with time zone, p_staff uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_t public.tenants;
  v_n public.news_posts;
begin
  select * into v_t from public.tenants where id = p_tenant;
  if not v_t.waitlist_free_slot_news or p_start < now() + interval '30 minutes' then return; end if;
  v_n := app.news_save(p_tenant, null, 'free_slot', 'Termin frei',
    to_char(p_start at time zone v_t.time_zone, 'DD.MM. "um" HH24:MI') || ' Uhr bei ' ||
    (select display_name from public.staff where id = p_staff) || ' – jetzt in der App buchen.',
    null, p_start, 'system');
  perform app.news_publish(p_tenant, v_n.id);
end
$function$

CREATE OR REPLACE FUNCTION app.merge_customers(p_legacy uuid, p_portal uuid, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_l public.customers;
  v_p public.customers;
  v_moved jsonb := '{}'::jsonb;
  v_n int;
begin
  select * into v_l from public.customers where id = p_legacy for update;
  select * into v_p from public.customers where id = p_portal for update;
  if v_l.id is null or v_p.id is null or v_l.tenant_id <> v_p.tenant_id then raise exception 'not_found' using errcode = 'P0001'; end if;
  if v_l.user_id is not null then raise exception 'already_linked' using errcode = 'P0001'; end if;
  if v_p.user_id is null then raise exception 'not_portal' using errcode = 'P0001'; end if;

  update public.appointments set customer_id = v_l.id where customer_id = v_p.id;
  get diagnostics v_n = row_count; v_moved := v_moved || jsonb_build_object('appointments', v_n);
  update public.chat_messages set customer_id = v_l.id where customer_id = v_p.id;
  get diagnostics v_n = row_count; v_moved := v_moved || jsonb_build_object('chat', v_n);
  update public.waitlist_entries set customer_id = v_l.id where customer_id = v_p.id;
  get diagnostics v_n = row_count; v_moved := v_moved || jsonb_build_object('waitlist', v_n);
  update public.waitlist_offers set customer_id = v_l.id where customer_id = v_p.id;
  update public.payments set customer_id = v_l.id where customer_id = v_p.id;
  get diagnostics v_n = row_count; v_moved := v_moved || jsonb_build_object('payments', v_n);
  update public.booking_attempts set customer_id = v_l.id where customer_id = v_p.id;
  update public.marketing_consents set customer_id = v_l.id where customer_id = v_p.id;
  update public.push_subscriptions set customer_id = v_l.id where customer_id = v_p.id;
  update public.notification_queue set customer_id = v_l.id where customer_id = v_p.id;
  update public.internal_notes set customer_id = v_l.id where customer_id = v_p.id;
  update public.crm_links set customer_id = v_l.id where customer_id = v_p.id;
  insert into public.news_reads (tenant_id, customer_id, news_id, read_at)
    select tenant_id, v_l.id, news_id, read_at from public.news_reads where customer_id = v_p.id on conflict do nothing;
  insert into public.notification_preferences (tenant_id, customer_id, kind, channel, enabled, updated_at)
    select tenant_id, v_l.id, kind, channel, enabled, updated_at from public.notification_preferences
    where customer_id = v_p.id on conflict do nothing;
  update public.link_suggestions set status = 'confirmed', decided_at = now(), decided_by = p_actor
    where portal_customer_id = v_p.id and legacy_customer_id = v_l.id;

  -- Portal-Zeile entfernen (Rest hängt per Cascade daran), dann die Bestandskundin mit dem Konto verbinden
  delete from public.customers where id = v_p.id;
  update public.customers set user_id = v_p.user_id, email = v_p.email, language = v_p.language,
    phone = coalesce(phone, v_p.phone), notify_email = v_p.notify_email, notify_sms = v_p.notify_sms and coalesce(phone, v_p.phone) is not null,
    marketing_consent = v_p.marketing_consent, marketing_consent_at = v_p.marketing_consent_at,
    privacy_notice_at = v_p.privacy_notice_at, avatar_path = coalesce(v_p.avatar_path, avatar_path)
  where id = v_l.id;
  perform app.audit(v_l.tenant_id, p_actor, 'merge', v_l.id, null,
    v_moved || jsonb_build_object('portalCustomerId', v_p.id, 'portalCustomerNumber', v_p.customer_number));
  return jsonb_build_object('customerId', v_l.id, 'moved', v_moved);
end
$function$

CREATE OR REPLACE FUNCTION app.new_customer_number(p_tenant uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_chars constant text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  v_bytes bytea;
  v_num text;
  i int;
begin
  loop
    v_bytes := extensions.gen_random_bytes(6);
    v_num := 'HB-';
    for i in 0..5 loop
      v_num := v_num || substr(v_chars, (get_byte(v_bytes, i) % 32) + 1, 1);
    end loop;
    exit when not exists (select 1 from public.customers where tenant_id = p_tenant and customer_number = v_num);
  end loop;
  return v_num;
end
$function$

CREATE OR REPLACE FUNCTION app.news_publish(p_tenant uuid, p_news uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_n public.news_posts;
  v_c record;
begin
  update public.news_posts set status = 'published', published_at = coalesce(published_at, now())
  where id = p_news and tenant_id = p_tenant and status = 'draft' returning * into v_n;
  if v_n.id is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  for v_c in select id from public.customers where tenant_id = p_tenant and deletion_requested_at is null loop
    perform app.enqueue_notification(p_tenant, v_c.id, 'news_promo', array['push', 'email', 'sms'],
      jsonb_build_object('title', v_n.title, 'body', left(v_n.body, 160), 'url', '/app/neuigkeiten?id=' || v_n.id),
      'news:' || v_n.id || ':' || v_c.id);
  end loop;
  return app.news_json(v_n, false);
end
$function$

CREATE OR REPLACE FUNCTION app.news_save(p_tenant uuid, p_id uuid, p_kind text, p_title text, p_body text, p_image_path text, p_valid_until timestamp with time zone, p_actor text)
 RETURNS news_posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_n public.news_posts;
begin
  if p_image_path is not null and p_image_path not like p_tenant::text || '/%' then
    raise exception 'invalid_path' using errcode = 'P0001';
  end if;
  if p_id is null then
    insert into public.news_posts (tenant_id, kind, title, body, image_path, valid_until, created_by)
    values (p_tenant, p_kind, btrim(p_title), btrim(p_body), p_image_path, p_valid_until, p_actor) returning * into v_n;
  else
    update public.news_posts set kind = p_kind, title = btrim(p_title), body = btrim(p_body), image_path = p_image_path,
      valid_until = p_valid_until
    where id = p_id and tenant_id = p_tenant and status = 'draft' returning * into v_n;
    if v_n.id is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  end if;
  return v_n;
end
$function$

CREATE OR REPLACE FUNCTION app.on_appointment_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if old.hold_kind is null and old.status in ('pending', 'confirmed') and old.starts_at > now()
     and (new.status = 'cancelled' or new.starts_at <> old.starts_at or new.staff_id <> old.staff_id) then
    begin
      perform app.waitlist_release(old.tenant_id, old.staff_id, old.starts_at, old.ends_at);
    exception when others then
      -- nie die eigentliche Absage/Verschiebung blockieren
      raise warning 'waitlist_release fehlgeschlagen: %', sqlerrm;
    end;
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION app.refund_for_cancel(p_appointment uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_a public.appointments;
  v_t public.tenants;
  v_p public.payments;
begin
  select * into v_a from public.appointments where id = p_appointment;
  select * into v_t from public.tenants where id = v_a.tenant_id;
  for v_p in select * from public.payments where appointment_id = p_appointment for update loop
    if v_p.status = 'paid' then
      update public.payments set status = 'refund_pending', updated_at = now(),
        refund_cents = case when v_a.starts_at - now() >= make_interval(hours => v_t.change_notice_hours)
                            then v_p.amount_cents
                            else round(v_p.amount_cents * (100 - v_t.late_cancel_keep_percent) / 100.0) end
      where id = v_p.id;
      update public.payments set status = 'paid' where id = v_p.id and refund_cents = 0;
    elsif v_p.status in ('requires_payment', 'processing') then
      update public.payments set status = 'cancelled', updated_at = now() where id = v_p.id;
    end if;
  end loop;
end
$function$

CREATE OR REPLACE FUNCTION app.slot_ok(p_tenant uuid, p_staff uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_ignore uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tz text;
  v_ls timestamp;
  v_le timestamp;
  v_dow int;
  v_oh public.opening_hours;
  v_sh public.staff_hours;
begin
  select time_zone into v_tz from public.tenants where id = p_tenant;
  v_ls := p_start at time zone v_tz;
  v_le := p_end at time zone v_tz;
  if v_ls::date <> v_le::date then
    return false;
  end if;
  v_dow := extract(dow from v_ls);

  select * into v_oh from public.opening_hours where tenant_id = p_tenant and weekday = v_dow;
  if not found or v_ls::time < v_oh.opens or v_le::time > v_oh.closes then
    return false;
  end if;

  if exists (select 1 from public.staff_hours h where h.staff_id = p_staff) then
    select * into v_sh from public.staff_hours h where h.staff_id = p_staff and h.weekday = v_dow;
    if not found or v_ls::time < v_sh.starts or v_le::time > v_sh.ends then
      return false;
    end if;
  end if;

  return not exists (
    select 1 from public.appointments a
    where a.staff_id = p_staff
      and a.status in ('pending', 'confirmed')
      and tstzrange(a.starts_at, a.ends_at, '[)') && tstzrange(p_start, p_end, '[)')
      and (p_ignore is null or a.id <> p_ignore));
end
$function$

CREATE OR REPLACE FUNCTION app.unlink_portal(p_customer uuid, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_c public.customers;
  v_new uuid;
begin
  select * into v_c from public.customers where id = p_customer for update;
  if v_c.id is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  if v_c.user_id is null then raise exception 'not_linked' using errcode = 'P0001'; end if;
  update public.customers set user_id = null where id = v_c.id;
  insert into public.customers (tenant_id, user_id, first_name, last_name, email, phone, language, notify_email,
                                marketing_consent, marketing_consent_at, privacy_notice_at)
  values (v_c.tenant_id, v_c.user_id, v_c.first_name, v_c.last_name, v_c.email, v_c.phone, v_c.language, v_c.notify_email,
          v_c.marketing_consent, v_c.marketing_consent_at, v_c.privacy_notice_at)
  returning id into v_new;
  -- die Bestandskundin behält ihre E-Mail nur, wenn sie nicht mit der neuen Portal-Zeile kollidiert (gleiche Person)
  perform app.audit(v_c.tenant_id, p_actor, 'unlink', v_c.id, null, jsonb_build_object('newPortalCustomerId', v_new));
  update public.link_suggestions set status = 'rejected', decided_at = now(), decided_by = p_actor
    where legacy_customer_id = v_c.id and status = 'confirmed';
  return jsonb_build_object('legacyCustomerId', v_c.id, 'portalCustomerId', v_new);
end
$function$

CREATE OR REPLACE FUNCTION app.waitlist_expire_offers()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_n int := 0;
begin
  for v_id in select id from public.waitlist_offers where status = 'offered' and expires_at <= now()
              order by expires_at for update skip locked loop
    perform app.waitlist_close_offer(v_id, 'expired');
    v_n := v_n + 1;
  end loop;
  return v_n;
end
$function$

CREATE OR REPLACE FUNCTION app.waitlist_offer_next(p_tenant uuid, p_staff uuid, p_slot_start timestamp with time zone, p_slot_end timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_t public.tenants;
  v_lead interval;
  v_win interval;
  v_exp timestamptz;
  v_ls timestamp;
  v_e public.waitlist_entries;
  v_s public.services;
  v_hold uuid;
  v_offer uuid;
  v_cat text;
  v_staff_name text;
begin
  select * into v_t from public.tenants where id = p_tenant;
  v_lead := p_slot_start - now();
  if v_lead <= interval '0' then return null; end if;
  -- Antwortfenster = Vorlauf / Divisor, begrenzt auf [min, max]
  v_win := make_interval(secs => greatest(v_t.offer_window_min_minutes * 60,
             least(v_t.offer_window_max_minutes * 60, extract(epoch from v_lead) / v_t.offer_window_divisor)));
  v_exp := now() + v_win;
  -- Fenster ginge über den Terminbeginn hinaus → kein Angebot mehr möglich, Slot ist normal buchbar
  if v_exp > p_slot_start then return null; end if;
  v_ls := p_slot_start at time zone v_t.time_zone;
  select display_name into v_staff_name from public.staff where id = p_staff;

  for v_e in
    select e.* from public.waitlist_entries e
    where e.tenant_id = p_tenant and e.status = 'active'
      and v_ls::date between e.date_from and e.date_to
      and extract(dow from v_ls)::smallint = any (e.weekdays)
      and (e.staff_id is null or e.staff_id = p_staff)
      and (e.short_notice or v_lead >= make_interval(hours => v_t.short_notice_hours))
      and not exists (select 1 from public.waitlist_offers o
                      where o.entry_id = e.id and o.staff_id = p_staff and o.slot_starts_at = p_slot_start)
      and not exists (select 1 from public.waitlist_offers o where o.entry_id = e.id and o.status = 'offered')
      and not exists (select 1 from public.appointments a
                      where a.customer_id = e.customer_id and a.status in ('pending', 'confirmed')
                        and tstzrange(a.starts_at, a.ends_at, '[)') && tstzrange(p_slot_start, p_slot_end, '[)'))
    order by e.created_at, e.id
  loop
    -- erste gewünschte Leistung, die die Mitarbeiterin anbietet und in Slot + Tageszeit-Fenster passt
    select s.* into v_s
    from unnest(v_e.service_ids) with ordinality u(sid, ord)
    join public.services s on s.id = u.sid and s.tenant_id = p_tenant and s.active
    join public.staff_services ss on ss.service_id = s.id and ss.staff_id = p_staff
    where p_slot_start + make_interval(mins => s.duration_minutes) <= p_slot_end
      and v_ls::time >= v_e.time_from
      and ((p_slot_start + make_interval(mins => s.duration_minutes)) at time zone v_t.time_zone)::time <= v_e.time_to
    order by u.ord limit 1;
    continue when v_s.id is null;

    select key into v_cat from public.service_categories where id = v_s.category_id;
    begin
      insert into public.appointments (tenant_id, customer_id, service_id, staff_id, service_name, category_key, staff_name,
        starts_at, ends_at, duration_minutes, price_eur, status, payment, hold_kind, hold_expires_at)
      values (p_tenant, v_e.customer_id, v_s.id, p_staff, v_s.name, v_cat, v_staff_name, p_slot_start,
        p_slot_start + make_interval(mins => v_s.duration_minutes), v_s.duration_minutes, v_s.price_eur,
        'pending', 'in_salon', 'waitlist_offer', v_exp)
      returning id into v_hold;
    exception when exclusion_violation then
      return null; -- Slot ist inzwischen anderweitig belegt
    end;
    insert into public.waitlist_offers (tenant_id, entry_id, customer_id, appointment_id, staff_id, service_id,
      slot_starts_at, slot_ends_at, starts_at, ends_at, expires_at)
    values (p_tenant, v_e.id, v_e.customer_id, v_hold, p_staff, v_s.id, p_slot_start, p_slot_end, p_slot_start,
      p_slot_start + make_interval(mins => v_s.duration_minutes), v_exp)
    returning id into v_offer;
    -- von der Kundin angefordert → kein Werbe-Häkchen nötig; alle Kanäle gleichzeitig, erster Klick zählt
    perform app.enqueue_notification(p_tenant, v_e.customer_id, 'waitlist', array['push', 'sms', 'email', 'inapp'],
      jsonb_build_object('title', 'Ihr Wunschtermin ist frei',
        'body', v_s.name || ' am ' || to_char(v_ls, 'DD.MM.') || ' um ' || to_char(v_ls, 'HH24:MI') || ' Uhr – bitte bis '
                || to_char(v_exp at time zone v_t.time_zone, 'HH24:MI') || ' Uhr antworten.',
        'url', '/app/angebot/' || v_offer, 'expiresAt', v_exp, 'offerId', v_offer),
      'offer:' || v_offer);
    return v_offer;
  end loop;

  perform app.free_slot_news(p_tenant, p_slot_start, p_staff);
  return null;
end
$function$

CREATE OR REPLACE FUNCTION public.available_slots(p_service_id uuid, p_staff_id uuid, p_date date)
 RETURNS TABLE(start text, staff_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
declare
  v_tenant uuid := app.current_tenant();
  v_t public.tenants;
  v_s public.services;
  v_oh public.opening_hours;
  v_today date;
  v_cur timestamp;
  v_st timestamptz;
  v_en timestamptz;
  v_m record;
begin
  if v_tenant is null then
    return;
  end if;
  select * into v_t from public.tenants where id = v_tenant;
  select * into v_s from public.services where id = p_service_id and tenant_id = v_tenant and active;
  if not found then
    return;
  end if;
  v_today := (now() at time zone v_t.time_zone)::date;
  if p_date < v_today or p_date > v_today + v_t.booking_horizon_days then
    return;
  end if;
  select * into v_oh from public.opening_hours where tenant_id = v_tenant and weekday = extract(dow from p_date);
  if not found then
    return;
  end if;

  v_cur := p_date + v_oh.opens;
  while v_cur + make_interval(mins => v_s.duration_minutes) <= p_date + v_oh.closes loop
    v_st := v_cur at time zone v_t.time_zone;
    v_en := v_st + make_interval(mins => v_s.duration_minutes);
    if v_st >= now() + make_interval(mins => v_t.booking_lead_minutes) then
      for v_m in
        select f.id from public.staff f
        join public.staff_services ss on ss.staff_id = f.id and ss.service_id = v_s.id
        where f.tenant_id = v_tenant and f.active and (p_staff_id is null or f.id = p_staff_id)
        order by f.sort_order, f.id
      loop
        if app.slot_ok(v_tenant, v_m.id, v_st, v_en, null) then
          start := app.to_wall(v_st, v_t.time_zone);
          staff_id := v_m.id;
          return next;
          exit;
        end if;
      end loop;
    end if;
    v_cur := v_cur + make_interval(mins => v_t.slot_step_minutes);
  end loop;
end
$function$

CREATE OR REPLACE FUNCTION public.book_appointment(p_service_id uuid, p_staff_id uuid, p_start text, p_payment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tenant uuid := app.current_tenant();
  v_cust uuid := app.my_customer_id();
  v_t public.tenants;
  v_s public.services;
  v_staff uuid;
  v_st timestamptz;
  v_en timestamptz;
  v_hour int;
  v_day int;
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = 'P0001'; end if;
  if v_tenant is null then raise exception 'tenant_unknown' using errcode = 'P0001'; end if;
  if v_cust is null then raise exception 'not_registered' using errcode = 'P0001'; end if;
  if p_payment not in ('in_salon', 'online_demo') then raise exception 'invalid_payment' using errcode = 'P0001'; end if;

  select * into v_t from public.tenants where id = v_tenant;
  select * into v_s from public.services where id = p_service_id and tenant_id = v_tenant and active;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;

  -- Rate-Limit je Kundin
  select count(*) filter (where created_at > now() - interval '1 hour'), count(*)
    into v_hour, v_day
    from public.booking_attempts where customer_id = v_cust and created_at > now() - interval '1 day';
  if v_hour >= v_t.max_bookings_per_hour or v_day >= v_t.max_bookings_per_day then
    raise exception 'rate_limited' using errcode = 'P0001';
  end if;

  v_st := app.from_wall(p_start, v_t.time_zone);
  v_en := v_st + make_interval(mins => v_s.duration_minutes);
  if v_st < now() + make_interval(mins => v_t.booking_lead_minutes)
     or v_st > now() + make_interval(days => v_t.booking_horizon_days) then
    raise exception 'slot_taken' using errcode = 'P0001';
  end if;

  if p_staff_id is null then
    select f.id into v_staff
    from public.staff f join public.staff_services ss on ss.staff_id = f.id and ss.service_id = v_s.id
    where f.tenant_id = v_tenant and f.active and app.slot_ok(v_tenant, f.id, v_st, v_en, null)
    order by f.sort_order, f.id limit 1;
    if v_staff is null then raise exception 'slot_taken' using errcode = 'P0001'; end if;
  else
    if not exists (select 1 from public.staff f join public.staff_services ss on ss.staff_id = f.id and ss.service_id = v_s.id
                   where f.id = p_staff_id and f.tenant_id = v_tenant and f.active) then
      raise exception 'not_found' using errcode = 'P0001';
    end if;
    if not app.slot_ok(v_tenant, p_staff_id, v_st, v_en, null) then
      raise exception 'slot_taken' using errcode = 'P0001';
    end if;
    v_staff := p_staff_id;
  end if;

  insert into public.booking_attempts (tenant_id, customer_id) values (v_tenant, v_cust);

  begin
    insert into public.appointments (tenant_id, customer_id, service_id, staff_id, service_name, category_key, staff_name,
                                     starts_at, ends_at, duration_minutes, price_eur, status, payment)
    select v_tenant, v_cust, v_s.id, v_staff, v_s.name, c.key, f.display_name,
           v_st, v_en, v_s.duration_minutes, v_s.price_eur, 'confirmed', p_payment::public.payment_method
    from public.service_categories c, public.staff f
    where c.id = v_s.category_id and f.id = v_staff
    returning id into v_id;
  exception when exclusion_violation then
    -- gleichzeitige Buchung desselben Slots: Postgres hat die zweite abgewiesen
    raise exception 'slot_taken' using errcode = 'P0001';
  end;
  return app.appointment_json(v_id);
end
$function$

CREATE OR REPLACE FUNCTION public.book_with_payment(p_service_id uuid, p_staff_id uuid, p_start text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_appt jsonb;
  v_q jsonb;
  v_hold int;
  v_p public.payments;
begin
  v_q := public.payment_quote(p_service_id);
  v_appt := public.book_appointment(p_service_id, p_staff_id, p_start,
    case when (v_q->>'dueOnlineCents')::int > 0 then 'online_demo' else 'in_salon' end);
  if (v_q->>'dueOnlineCents')::int = 0 then
    return jsonb_build_object('appointment', v_appt, 'payment', null);
  end if;
  v_hold := (v_q->>'holdMinutes')::int;
  -- ausstehende Zahlung: Termin reserviert (Status pending, unter der Doppelbuchungs-Sperre), verfällt nach X Minuten
  update public.appointments set status = 'pending', hold_kind = 'payment',
    hold_expires_at = now() + make_interval(mins => v_hold), updated_at = now()
  where id = (v_appt->>'id')::uuid;
  insert into public.payments (tenant_id, appointment_id, customer_id, amount_cents, kind, idempotency_key)
  select a.tenant_id, a.id, a.customer_id, (v_q->>'dueOnlineCents')::int,
    case when v_q->>'mode' = 'full' then 'full' else 'deposit' end, 'appt:' || a.id
  from public.appointments a where a.id = (v_appt->>'id')::uuid
  returning * into v_p;
  return jsonb_build_object('appointment', app.appointment_json(v_p.appointment_id)
    || jsonb_build_object('holdKind', 'payment', 'holdExpiresAt', now() + make_interval(mins => v_hold)),
    'payment', app.payment_json(v_p));
end
$function$

CREATE OR REPLACE FUNCTION public.cancel_appointment(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cust uuid := app.my_customer_id();
  v_a public.appointments;
  v_notice int;
begin
  if v_cust is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  select * into v_a from public.appointments where id = p_id and customer_id = v_cust for update;
  if not found or v_a.status not in ('pending', 'confirmed') then raise exception 'not_found' using errcode = 'P0001'; end if;
  select change_notice_hours into v_notice from public.tenants where id = v_a.tenant_id;
  if v_a.starts_at < now() + make_interval(hours => v_notice) then raise exception 'too_late' using errcode = 'P0001'; end if;
  update public.appointments set status = 'cancelled', updated_at = now() where id = p_id;
  return app.appointment_json(p_id);
end
$function$

