CREATE OR REPLACE FUNCTION public.join_waitlist(p_service_ids uuid[], p_staff_id uuid, p_date_from date, p_date_to date, p_weekdays smallint[], p_time_from text, p_time_to text, p_short_notice boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid := app.my_customer_id();
  v_tenant uuid := app.current_tenant();
  v_e public.waitlist_entries;
begin
  if v_id is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  if (select count(*) from unnest(p_service_ids) u(sid) join public.services s on s.id = u.sid
      where s.tenant_id = v_tenant and s.active) <> cardinality(p_service_ids) then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  if p_staff_id is not null and not exists (select 1 from public.staff where id = p_staff_id and tenant_id = v_tenant and active) then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  if p_date_from < (now() at time zone 'Europe/Vienna')::date then raise exception 'invalid_range' using errcode = 'P0001'; end if;
  if (select count(*) from public.waitlist_entries where customer_id = v_id and status = 'active') >= 10 then
    raise exception 'rate_limited' using errcode = 'P0001';
  end if;
  insert into public.waitlist_entries (tenant_id, customer_id, service_ids, staff_id, date_from, date_to, weekdays,
    time_from, time_to, short_notice)
  values (v_tenant, v_id, p_service_ids, p_staff_id, p_date_from, p_date_to, p_weekdays, p_time_from::time,
    p_time_to::time, coalesce(p_short_notice, false))
  returning * into v_e;
  return to_jsonb(v_e);
end
$function$

CREATE OR REPLACE FUNCTION public.leave_waitlist(p_entry_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_offer uuid;
begin
  update public.waitlist_entries set status = 'cancelled'
  where id = p_entry_id and customer_id = app.my_customer_id() and status = 'active';
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  select id into v_offer from public.waitlist_offers where entry_id = p_entry_id and status = 'offered';
  if v_offer is not null then perform app.waitlist_close_offer(v_offer, 'withdrawn'); end if;
end
$function$

CREATE OR REPLACE FUNCTION public.payment_quote(p_service_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_s public.services;
  v_r public.payment_rules;
  v_total int;
  v_due int;
begin
  select * into v_s from public.services where id = p_service_id and tenant_id = app.current_tenant() and active;
  if v_s.id is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  v_r := app.payment_rule(v_s.tenant_id, v_s.id);
  v_total := round(v_s.price_eur * 100);
  v_due := case coalesce(v_r.mode, 'on_site')
    when 'deposit_percent' then round(v_total * v_r.value / 100)
    when 'deposit_fixed' then least(v_total, round(v_r.value * 100))
    when 'full' then v_total else 0 end;
  return jsonb_build_object('mode', coalesce(v_r.mode, 'on_site'), 'totalCents', v_total, 'dueOnlineCents', v_due,
    'holdMinutes', (select payment_hold_minutes from public.tenants where id = v_s.tenant_id));
end
$function$

CREATE OR REPLACE FUNCTION public.register_customer(p_first_name text, p_last_name text, p_phone text, p_language text, p_marketing boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_tenant uuid := app.current_tenant();
  v_email text := lower(auth.jwt() ->> 'email');
  v_c public.customers;
  v_confirmed boolean;
  v_auto boolean;
  v_legacy uuid;
  v_hits int;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = 'P0001'; end if;
  if v_tenant is null then raise exception 'tenant_unknown' using errcode = 'P0001'; end if;
  if v_email is null then raise exception 'email_missing' using errcode = 'P0001'; end if;

  select * into v_c from public.customers where tenant_id = v_tenant and user_id = v_uid;
  if found then
    if v_c.deletion_requested_at is not null then raise exception 'not_found' using errcode = 'P0001'; end if;
    return app.profile_json(v_c);
  end if;
  if exists (select 1 from public.customers where tenant_id = v_tenant and user_id is not null and lower(email) = v_email) then
    raise exception 'email_taken' using errcode = 'P0001';
  end if;

  insert into public.customers (tenant_id, user_id, first_name, last_name, email, phone, language,
                                marketing_consent, marketing_consent_at)
  values (v_tenant, v_uid, trim(p_first_name), trim(p_last_name), v_email, nullif(trim(coalesce(p_phone, '')), ''),
          coalesce(nullif(p_language, ''), 'de'), coalesce(p_marketing, false),
          case when coalesce(p_marketing, false) then now() end)
  returning * into v_c;

  v_hits := app.find_link_suggestions(v_c.id);
  select (email_confirmed_at is not null) into v_confirmed from auth.users where id = v_uid;
  select coalesce(auto_link_verified, false) into v_auto from public.app_settings where tenant_id = v_tenant;
  if v_hits = 1 and coalesce(v_auto, false) and coalesce(v_confirmed, false) then
    select legacy_customer_id into v_legacy from public.link_suggestions where portal_customer_id = v_c.id;
    perform app.merge_customers(v_legacy, v_c.id, 'auto');
    select * into v_c from public.customers where id = v_legacy;
  end if;
  return app.profile_json(v_c);
end
$function$

CREATE OR REPLACE FUNCTION public.reschedule_appointment(p_id uuid, p_new_start text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cust uuid := app.my_customer_id();
  v_a public.appointments;
  v_t public.tenants;
  v_st timestamptz;
  v_en timestamptz;
begin
  if v_cust is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  select * into v_a from public.appointments where id = p_id and customer_id = v_cust for update;
  if not found or v_a.status not in ('pending', 'confirmed') then raise exception 'not_found' using errcode = 'P0001'; end if;
  select * into v_t from public.tenants where id = v_a.tenant_id;
  if v_a.starts_at < now() + make_interval(hours => v_t.change_notice_hours) then raise exception 'too_late' using errcode = 'P0001'; end if;

  v_st := app.from_wall(p_new_start, v_t.time_zone);
  v_en := v_st + make_interval(mins => v_a.duration_minutes);
  if v_st < now() + make_interval(mins => v_t.booking_lead_minutes)
     or v_st > now() + make_interval(days => v_t.booking_horizon_days)
     or not app.slot_ok(v_t.id, v_a.staff_id, v_st, v_en, v_a.id) then
    raise exception 'slot_taken' using errcode = 'P0001';
  end if;
  begin
    update public.appointments set starts_at = v_st, ends_at = v_en, updated_at = now() where id = p_id;
  exception when exclusion_violation then
    raise exception 'slot_taken' using errcode = 'P0001';
  end;
  return app.appointment_json(p_id);
end
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
  tbl name;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        SELECT c.relname INTO tbl FROM pg_catalog.pg_class c WHERE c.oid = cmd.objid;
        EXECUTE format('alter table if exists %I.%I enable row level security', cmd.schema_name, tbl);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

